(1949,557,'Paso 1: \\( f(x) = 5x \\) es una función lineal.',1,'2025-11-04 22:06:20','2025-11-04 22:06:20'),
(1950,557,'Paso 2: La derivada de \\( ax \\), donde \\( a \\) es constante, es \\( a \\).',2,'2025-11-04 22:06:20','2025-11-04 22:06:20'),
